CREATE TABLE IF NOT EXISTS cms_update_history(id INTEGER PRIMARY KEY AUTOINCREMENT,component_type TEXT NOT NULL,component_key TEXT NOT NULL,before_version TEXT,before_checksum TEXT,after_version TEXT,after_checksum TEXT,actor_id INTEGER REFERENCES users(id) ON DELETE SET NULL,status TEXT NOT NULL CHECK(status IN('started','succeeded','failed','rolled_back','quarantined')),snapshot_path TEXT,health_json TEXT NOT NULL DEFAULT '{}',error_message TEXT,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT);
CREATE TABLE IF NOT EXISTS cms_package_quarantine(id INTEGER PRIMARY KEY AUTOINCREMENT,extension_key TEXT NOT NULL,version TEXT,checksum TEXT,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','released')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,released_at TEXT,UNIQUE(extension_key,version,checksum));
CREATE TABLE IF NOT EXISTS cms_security_advisories(id INTEGER PRIMARY KEY AUTOINCREMENT,advisory_key TEXT NOT NULL UNIQUE,extension_key TEXT,affected_constraint TEXT NOT NULL DEFAULT '*',severity TEXT NOT NULL CHECK(severity IN('low','medium','high','critical')),title TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',action TEXT NOT NULL DEFAULT 'warn' CHECK(action IN('warn','quarantine','block')),source TEXT NOT NULL DEFAULT 'local',published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_trust_scans(id INTEGER PRIMARY KEY AUTOINCREMENT,scan_key TEXT NOT NULL UNIQUE,checked_extensions INTEGER NOT NULL DEFAULT 0,quarantined INTEGER NOT NULL DEFAULT 0,blocked INTEGER NOT NULL DEFAULT 0,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.21.0');